c = C()
print(c.__dict__)  # {'x': 1}
```

Adds items to a dict or set.

**Examples:**
```python
d = {'a': 1}
d.update({'b': 2})  # {'a': 1, 'b': 2}
s = {1}
s.update([2, 3])  # {1, 2, 3}
```

Gets value or sets default if key missing.

**Example:**
```python
d = {'a': 1}
x = d.setdefault('b', 2)  # x = 2, d = {'a': 1, 'b': 2}
```

Memoizes function calls.

**Example:**
```python
from functools import lru_cache
@lru_cache
def fib(n):
    return n if n < 2 else fib(n-1) + fib(n-2)
print(fib(10))  # 55
```

Defines length.

**Example:**
```python
class C:
    def __init__(self):
        self.data = [1, 2]
    def __len__(self):
        return len(self.data)
c = C()
print(len(c))  # 2
```

Makes object iterable.

**Example:**
```python
class C:
    def __init__(self):
        self.data = [1, 2]
    def __iter__(self):
        return iter(self.data)
c = C()
for x in c:
    print(x)  # 1, 2
```

Defines iterator behavior.

**Example:**
```python
class C:
    def __init__(self):
        self.n = 0
    def __iter__(self):
        return self
    def __next__(self):
        if self.n < 2:
            self.n += 1
            return self.n
        raise StopIteration
c = C()
for x in c:
    print(x)  # 1, 2
```

Defines addition.

**Example:**
```python
class C:
    def __init__(self, x):
        self.x = x
    def __add__(self, other):
        return C(self.x + other.x)
    def __str__(self):
        return str(self.x)
c1 = C(2)
c2 = C(3)
print(c1 + c2)  # 5
```

