    def __init_subclass__(cls):
        cls.x = 1
class Sub(Base):
    pass
print(Sub.x)  # 1
```

Customizes `isinstance()`.

**Example:**
```python
class C:
    @classmethod
    def __subclasshook__(cls, sub):
        return True
print(isinstance(5, C))  # True
```

Customizes class namespace.

**Example:**
```python
class Meta(type):
    @classmethod
    def __prepare__(mcs, name, bases):
        return {'x': 1}
class C(metaclass=Meta):
    pass
print(C.x)  # 1
```

